/// This trait is used to print attributes in `rustc_hir_pretty`.
///
/// For structs and enums it can be derived using [`rustc_macros::PrintAttribute`].
/// The output will look a lot like a `Debug` implementation, but fields of several types
/// like [`Span`]s and empty tuples, are gracefully skipped so they don't clutter the
/// representation much.
export interface PrintAttribute<T> {
  /// Whether or not this will render as something meaningful, or if it's skipped
  /// (which will force the containing struct to also skip printing a comma
  /// and the field name).
  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:30 should_render
  should_render(self: T): boolean;

  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:32 print_attribute
  print_attribute(self: T, p: Printer): void;
}

// impl<T: PrintAttribute> PrintAttribute for &T
export function print_attribute_ref<T>(t: PrintAttribute<T>): PrintAttribute<T> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:36 should_render
    should_render(self: T): boolean {
      return t.should_render(self);
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:40 print_attribute
    print_attribute(self: T, p: Printer): void {
      t.print_attribute(self, p);
    },
  };
}
// impl<T: PrintAttribute> PrintAttribute for Box<T>
export function print_attribute_Box<T>(t: PrintAttribute<T>): PrintAttribute<T> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:45 should_render
    should_render(self: T): boolean {
      return t.should_render(self);
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:49 print_attribute
    print_attribute(self: T, p: Printer): void {
      t.print_attribute(self, p);
    },
  };
}
// impl<T: PrintAttribute> PrintAttribute for Option<T>
export function print_attribute_Option<T>(t: PrintAttribute<T>): PrintAttribute<T | undefined> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:54 should_render
    should_render(self: T | undefined): boolean {
      return self !== undefined && t.should_render(self);
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:58 print_attribute
    print_attribute(self: T | undefined, p: Printer): void {
      if (self !== undefined) {
        t.print_attribute(self, p);
      }
    },
  };
}
// impl<T: PrintAttribute> PrintAttribute for ThinVec<T>
export function print_attribute_ThinVec<T>(t: PrintAttribute<T>): PrintAttribute<readonly T[]> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:65 should_render
    should_render(self: readonly T[]): boolean {
      return self.length === 0 || t.should_render(self[0]!);
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:69 print_attribute
    print_attribute(self: readonly T[], p: Printer): void {
      let last_printed = false;
      p.word("[");
      for (const i of self) {
        if (last_printed) {
          p.word_space(",");
        }
        t.print_attribute(i, p);
        last_printed = t.should_render(i);
      }
      p.word("]");
    },
  };
}
// impl<T: PrintAttribute, T2: PrintAttribute> PrintAttribute for FxIndexMap<T, T2>
export function print_attribute_FxIndexMap<T, T2>(t: PrintAttribute<T>, t2: PrintAttribute<T2>): PrintAttribute<Map<T, T2>> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:83 should_render
    should_render(self: Map<T, T2>): boolean {
      // PORT: `self[0]` indexes an `IndexMap` by position: the *value* of the first entry.
      return self.size === 0 || t2.should_render(self.values().next().value!);
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:87 print_attribute
    print_attribute(self: Map<T, T2>, p: Printer): void {
      let last_printed = false;
      p.word("[");
      for (const [i] of self) {
        if (last_printed) {
          p.word_space(",");
        }
        t.print_attribute(i, p);
        last_printed = t.should_render(i);
      }
      p.word("]");
    },
  };
}
// impl PrintAttribute for PathBuf
// PORT: `PathBuf` is a UTF-8 string (typemap); `display()` is the string itself.
export const print_attribute_PathBuf: PrintAttribute<string> = {
  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:101 should_render
  should_render(_self: string): boolean {
    return true;
  },

  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:105 print_attribute
  print_attribute(self: string, p: Printer): void {
    p.word(self);
  },
};
// impl PrintAttribute for Path
export const print_attribute_Path: PrintAttribute<Path> = {
  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:110 should_render
  should_render(_self: Path): boolean {
    return true;
  },

  // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:114 print_attribute
  print_attribute(self: Path, p: Printer): void {
    p.word(join_path_idents(self.segments.map((seg) => seg.ident)));
  },
};

// macro_rules! print_skip: `impl PrintAttribute for $t` that renders nothing.
function print_skip<T>(): PrintAttribute<T> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:122 should_render
    should_render(_self: T): boolean {
      return false;
    },
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:123 print_attribute
    print_attribute(_self: T, _p: Printer): void {},
  };
}

// macro_rules! print_disp: `impl PrintAttribute for $t` printing `format!("{}", self)`.
// PORT: the `Display` of `$t` is passed in.
function print_disp<T>(display: (v: T) => string): PrintAttribute<T> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:131 should_render
    should_render(_self: T): boolean {
      return true;
    },
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:132 print_attribute
    print_attribute(self: T, p: Printer): void {
      p.word(display(self));
    },
  };
}
// macro_rules! print_debug: `impl PrintAttribute for $t` printing `format!("{:?}", self)`.
// PORT: the `Debug` of `$t` is passed in.
function print_debug<T>(debug: Debug<T>): PrintAttribute<T> {
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:141 should_render
    should_render(_self: T): boolean {
      return true;
    },
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:142 print_attribute
    print_attribute(self: T, p: Printer): void {
      p.word(debug(self, PLAIN));
    },
  };
}

// macro_rules! print_tup: `impl PrintAttribute for (A, B, ..)` (arities 1..=8: `print_tup!(A B C D E F G H)`).
// PORT: one function over the tables of the elements.
export function print_attribute_tuple<T extends readonly unknown[]>(ts: { readonly [K in keyof T]: PrintAttribute<T[K]> }): PrintAttribute<T> {
  const elems = ts as readonly PrintAttribute<unknown>[];
  // print_tup!(num_should_render $t $($ts)*)
  const num_should_render = (self: T): number => elems.reduce((n, t, i) => n + (t.should_render(self[i]) ? 1 : 0), 0);
  return {
    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:155 should_render
    should_render(self: T): boolean {
      return num_should_render(self) !== 0;
    },

    // rustc: compiler/rustc_attr_ir/src/pretty_printing.rs:160 print_attribute
    print_attribute(self: T, p: Printer): void {
      const parens = num_should_render(self) > 1;
      if (parens) {
        p.popen();
      }

      let printed_anything = elems[0]!.should_render(self[0]);

      elems[0]!.print_attribute(self[0], p);

      for (let i = 1; i < elems.length; i++) {
        if (elems[i]!.should_render(self[i])) {
          if (printed_anything) {
            p.word_space(",");
          }
          printed_anything = true;
        }
        elems[i]!.print_attribute(self[i], p);
      }

      if (parens) {
        p.pclose();
      }
    },
  };
}

